'use strict';
const feedbackForm=document.querySelector('#feedback-form'),feedbackMessage=document.querySelector('#feedback-message'),feedbackStatus=document.querySelector('#feedback-status'),feedbackFields=document.querySelector('#feedback-fields'),feedbackSubmit=document.querySelector('#feedback-submit');
const feedbackEndpoint='https://formsubmit.co/ajax/tianao1128@outlook.com';let feedbackSending=false;
function updateFeedbackCounter(){document.querySelector('#feedback-counter').textContent=`${feedbackMessage.value.length} / 3000`;feedbackMessage.setCustomValidity('');updateFeedbackMailto()}
function updateFeedbackMailto(){const name=document.querySelector('#feedback-name').value.trim()||'匿名访客',category=document.querySelector('#feedback-category').value;const body=`称呼：${name}\n类型：${category}\n\n${feedbackMessage.value}\n\n回复邮箱：${document.querySelector('#feedback-email').value.trim()||'未提供'}\n留言页面：${location.origin}${location.pathname}`;document.querySelector('#feedback-mailto').href=`mailto:tianao1128@outlook.com?subject=${encodeURIComponent('琴始网站 · '+category)}&body=${encodeURIComponent(body)}`}
feedbackForm.addEventListener('input',updateFeedbackCounter);feedbackForm.addEventListener('change',updateFeedbackMailto);
feedbackForm.addEventListener('submit',async event=>{event.preventDefault();if(feedbackSending)return;feedbackMessage.setCustomValidity('');if(feedbackMessage.value.trim().length<5){feedbackMessage.setCustomValidity('请至少写下 5 个字，方便站长了解你的想法。');feedbackMessage.reportValidity();return}if(!feedbackForm.reportValidity())return;if(feedbackForm.elements.namedItem('_honey').value){feedbackStatus.textContent='本次提交未通过检查，请刷新页面后重试。';return}const payload={name:document.querySelector('#feedback-name').value.trim()||'匿名访客',category:document.querySelector('#feedback-category').value,message:feedbackMessage.value.trim(),_subject:'琴始网站 · '+document.querySelector('#feedback-category').value,_template:'table',_url:location.origin+location.pathname};const email=document.querySelector('#feedback-email').value.trim();if(email)payload.email=email;feedbackSending=true;feedbackFields.disabled=true;feedbackSubmit.textContent='正在发送…';feedbackStatus.textContent='正在把小纸条交给收信服务，请稍等。';feedbackStatus.className='';const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),20000);try{const response=await fetch(feedbackEndpoint,{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json'},body:JSON.stringify(payload),signal:controller.signal});const result=await response.json();if(!response.ok||!(result.success===true||result.success==='true')){const issue=new Error('submission_not_confirmed');if(/needs activation|activate form/i.test(String(result.message||'')))issue.name='FeedbackActivationError';throw issue;}feedbackForm.hidden=true;document.querySelector('#feedback-success').hidden=false;document.querySelector('#feedback-again').focus();}catch(error){feedbackStatus.textContent=error.name==='FeedbackActivationError'?'站长的收信通道尚未完成开通，暂时无法确认留言送达。内容已保留，你可以稍后重试或直接写邮件。':'暂时无法确认是否提交成功。内容已为你保留，请稍后重试，或点击“直接写邮件”。';feedbackStatus.className='feedback-error';}finally{clearTimeout(timer);feedbackSending=false;feedbackFields.disabled=false;feedbackSubmit.innerHTML='发送留言 <span>→</span>';}});
document.querySelector('#feedback-again').onclick=()=>{feedbackForm.reset();feedbackStatus.textContent='';feedbackStatus.className='';document.querySelector('#feedback-success').hidden=true;feedbackForm.hidden=false;updateFeedbackCounter();feedbackMessage.focus()};
// Native POST remains usable when JavaScript is unavailable.
const pageUrl=document.createElement('input');pageUrl.type='hidden';pageUrl.name='_url';pageUrl.value=location.origin+location.pathname;feedbackForm.append(pageUrl);updateFeedbackCounter();
